from author import C,S,R,P,T
c=C('定积分的面积与体积应用')
S(c,'面积：先求交点，再写上减下',[R('例题曲线',r"y=x,\quad y=x^2"),R('求交点',r"x=x^2\quad\Longrightarrow\quad x=0,1"),R('区间内上下关系',r"x-x^2\ge0\quad(0\le x\le1)"),R('面积',r"S=\int_0^1(x-x^2)dx=\frac12-\frac13=\frac16")],[P('定积分面积题先画简图或代点确认关系，再解交点找上下限。按x积分时写上方曲线减下方曲线。例题直线y等于x和抛物线y等于x平方，交点横坐标零和一；在零到一之间，直线在上，因此被积式是x减x平方。不要把两条曲线相减的顺序交给记忆，要在当前区间确认。',[1,2,3],['交点确定积分上下限','对x积分用上方减下方']),P('积分后是二分之一减三分之一，面积六分之一。面积应为非负，若你算出负值，先检查上下曲线或积分方向。若两条曲线在中间交换了上下位置，就要按交点分段，分别上减下再相加；不能用一整段有符号积分让正负部分互相抵消，最后只加一个绝对值来碰运气。',[4],['面积非负；换位时分段','有符号积分不能直接代替总面积'])],['定积分求面积'])
S(c,'面积也可以对y积分',[R('横着写的边界',r"x=y^2,\quad x=1"),R('交点纵坐标',r"y^2=1\quad\Longrightarrow\quad y=-1,1"),R('右减左',r"S=\int_{-1}^1(1-y^2)dy"),R('结果',r"S=2\int_0^1(1-y^2)dy=\frac43")],[P('如果边界本来写成x等于y的函数，或者横着分段更少，可以改对y积分。这时减法是右边界减左边界，上下限写交点的纵坐标。例题x等于y平方与竖线x等于一，交点y为负一和一，右边是直线一，左边是y平方，所以写一减y平方。',[1,2,3],['对y积分用右减左','上下限必须使用y的取值']),P('一减y平方是偶函数，可以算零到一再乘二，结果三分之四。具体计算是二乘以一减三分之一，也就是二乘以三分之二。选择对x还是对y积分，考试中主要看哪一种边界更简单、需要分段更少，但选好以后变量、边界和上下限要始终一致。',[4],['二乘一减三分之一等于三分之四','积分变量与端点坐标配套'])],['定积分求面积','定积分偶倍奇零'])
S(c,'绕x轴体积：外半径平方减内半径平方',[R('圆环法模板',r"V=\pi\int_a^b\left[R(x)^2-r(x)^2\right]dx"),R('例题区域',r"x^2\le y\le x,\quad0\le x\le1"),R('绕x轴的半径',r"R=x,\quad r=x^2"),R('计算',r"V=\pi\int_0^1(x^2-x^4)dx=\frac{2\pi}{15}")],[P('绕轴旋转的体积题，先确认旋转轴，再找截面外半径与内半径。圆环法是π乘外半径平方减内半径平方，再沿轴积分。半径是到旋转轴的距离，不能机械把一个可能为负的函数值直接当作距离。若区域跨过旋转轴，也要重新确定是否有孔以及哪一侧决定外半径。',[1,2],['先确定轴，再确定两种半径','公式是平方之差']),P('例题还是零到一之间的直线与抛物线区域，绕x轴时外半径x，内半径x平方。被积式是x平方减x四次方，算出二π除以十五。不要先把上减下平方，半径差的平方与两个半径平方的差不同；也不要把面积答案再随意乘一次π当作旋转体体积。',[3,4],['不能把R减r整体平方','本题结果二π除以十五'])],['定积分求绕轴旋转的旋转体体积'])
S(c,'绕y轴：换成y边界或用壳法',[R('同一区域改写',r"y\le x\le\sqrt{y},\quad0\le y\le1"),R('绕y轴圆环法',r"V=\pi\int_0^1\left[(\sqrt{y})^2-y^2\right]dy=\frac\pi6"),R('另一条可用路线',r"V=2\pi\int_0^1x(x-x^2)dx=\frac\pi6"),T('圆柱壳记法','二π × 壳半径 × 壳高度，对x积分')],[P('同一区域绕y轴，若用圆环法就改成对y积分。由x平方等于y得到右边界根号y，由x等于y得到左边界y，外半径根号y、内半径y，积分结果π除以六。虽然两次都是同一块平面区域，换了旋转轴，体积也会变，不能复用上一页的半径。',[1,2],['绕y轴圆环法通常改对y积分','先把曲线写成x关于y的函数']),P('也可以用圆柱壳法，直接保留对x积分：二π乘壳半径x，再乘高度x减x平方，积分仍得到π除以六。这是一条备选计算模板，不必为它另背证明。考试时选择自己能清楚识别半径和高度的方法，并把它们写在积分式旁边，避免只有一个公式却说不清各项来自哪里。',[3,4],['壳法是二π乘半径乘高度','两种方法不能混用半径与微分'])],['定积分求绕轴旋转的旋转体体积'])
S(c,'面积体积练习',[R('区域',r"0\le y\le x,\quad0\le x\le1"),R('任务',r"S=\ ?\qquad V_x=\ ?")],[P('暂停计算：零到一之间，直线y等于x与x轴围出的区域，先求面积，再求绕x轴旋转的体积。先分别写积分式，不要急着积分。面积的被积式是高度，圆盘体积的被积式涉及半径的平方，两道题的公式不能只靠最后是否带π来区分。',[1,2],['先分别写出两个积分式','答案在下一页'])],['定积分求面积','定积分求绕轴旋转的旋转体体积'],kind='question')
S(c,'面积体积练习答案',[R('面积',r"S=\int_0^1x\,dx=\frac12"),R('绕x轴体积',r"V_x=\pi\int_0^1x^2dx=\frac\pi3")],[P('面积是x从零到一的积分，得到二分之一。绕x轴时没有内孔，内半径为零、外半径为x，所以体积是π乘x平方的积分，得到π除以三。两式都可以很快套基本幂函数公式，但写被积式之前，先分清题目问平面面积还是旋转体体积，才不会在第一步就丢掉关键平方。',[1,2],['面积二分之一，体积π除以三','体积计算的半径需要平方'])],['定积分求面积','定积分求绕轴旋转的旋转体体积'],kind='answer')

c=C('微分方程与考前回顾')
S(c,'先识别阶数与方程类型',[R('一阶与二阶',r"y^{\prime}+y=x,\qquad y^{\prime\prime}-3y^{\prime}+2y=0"),R('阶数看最高阶导数',r"(y^{\prime\prime})^2+y=0:\quad n=2"),R('线性要求',r"a_n(x)y^{(n)}+\cdots+a_1(x)y^{\prime}+a_0(x)y=Q(x)"),R('初值用于确定常数',r"y(0)=1,\quad y^{\prime}(0)=0")],[P('微分方程的未知量是一整个函数。先看最高出现几阶导数，那就是阶数，不看这个导数有没有平方。含y两撇的平方仍然是二阶，但已经不是线性。线性方程要求未知函数及其导数都只以一次出现，彼此不相乘，系数可以是自变量x的函数。先分类型，再选择对应模板。',[1,2,3],['阶数看导数阶数，不看幂次','线性不允许y与导数互相相乘']),P('通解包含任意常数，给了初值以后再确定常数，得到符合该条件的特解。常见n阶线性方程的通解有n个独立常数，所以一阶题通常确定一个，二阶题通常要两条独立条件。别把右边等于零当成未知函数只能取零，齐次线性方程照样可以有许多非零解。',[4],['先求通解，再代初值','右端为零不表示只有零解'])],['微分方程的相关概念'])
S(c,'可分离变量：一侧留y，一侧留x',[R('识别模板',r"\frac{dy}{dx}=g(x)h(y)"),R('分离并积分',r"\int\frac{dy}{h(y)}=\int g(x)dx"),R('例题',r"y^{\prime}=xy,\quad\frac{dy}{y}=x\,dx\quad(y\ne0)"),R('积分结果',r"\ln|y|=\frac{x^2}{2}+C"),R('整理且补回零解',r"y=C e^{x^2/2},\quad C\in\mathbb R")],[P('可分离变量的识别标志，是右边能够拆成只含x的因子乘只含y的因子。把含y部分和dy放一边，含x部分和dx放另一边，再分别积分。例题y撇等于xy，除以y以后得到dy除以y等于x乘dx。这里除以y暂时要求y非零，所以要记住最后检查是否漏掉常数解。',[1,2,3],['先分离，再分别积分','除以h(y)前要记下被排除的常数解']),P('积分得到自然对数绝对值y等于x平方的一半加常数，整理为y等于C乘e的x平方一半次方。把C允许取任意实数时，正负解和零解都包括进来。若给y在零处等于二，就得到C等于二。不要把取指数以后出现的常数仍机械限定为正数而丢掉原方程允许的其他解。',[4,5],['本题整理后的C可正可负也可为零','代初值后再确定C'])],['可分离变量微分方程'])
S(c,'一阶线性：标准式与积分因子',[R('标准式',r"y^{\prime}+P(x)y=Q(x)"),R('积分因子',r"\mu(x)=e^{\int P(x)dx}"),R('相乘后识别完整导数',r"(\mu y)^{\prime}=\mu Q"),R('通解',r"y=\frac1\mu\left(\int\mu Q\,dx+C\right)")],[P('一阶线性方程先整理成y撇系数为一，再读出P和Q。计算积分因子μ，等于e的P积分次方；这里选择一个方便的积分因子即可，不必把任意常数反复带进去。然后整条方程乘μ，左边就可以写成μ乘y这个乘积的导数，右边是μ乘Q。',[1,2,3],['先把y撇系数化为一','P的正负号直接影响积分因子']),P('两边积分后得到μ乘y等于右边的积分加C，最后除以μ。整套步骤是标准式、积分因子、完整导数、积分、解出y。模板看起来长，但每一步都固定。若一开始的方程是二倍y撇加其他项，必须先整体除以二，不能只把y撇前的二擦掉却不改右侧。',[4],['整式相除才能标准化','积分后还要除以积分因子'])],['一阶线性微分方程'])
S(c,'一阶线性例题：带初值定常数',[R('题目',r"y^{\prime}-2y=e^x,\quad y(0)=0"),R('积分因子',r"P=-2,\quad\mu=e^{-2x}"),R('积分',r"(e^{-2x}y)^{\prime}=e^{-x}\quad\Longrightarrow\quad e^{-2x}y=-e^{-x}+C"),R('通解与初值',r"y=Ce^{2x}-e^x,\quad C=1"),R('特解',r"y=e^{2x}-e^x")],[P('这题已经是标准式，P等于负二，因此积分因子是e的负二x次方。整条方程相乘后，右边e的x次方与它相乘变成e的负x次方；左边是积分因子乘y的导数。积分得到负的e的负x次方加C，这里内部负号带来的积分负号不要漏掉。',[1,2,3],['P是负二，积分因子有负号','右侧指数相乘要把指数相加']),P('再除以e的负二x次方，得到通解C乘e的二x次方减e的x次方。把x等于零、y等于零代入，零等于C减一，所以C为一，最后得到第五行。算完可以把y和它的导数代回原方程，检查左边是否恢复e的x次方，同时检查初值是否成立。',[4,5],['先求通解，最后代初值','原方程和初值都应满足'])],['一阶线性微分方程'])
S(c,'二阶常系数齐次：先解特征方程',[R('标准形式',r"y^{\prime\prime}+py^{\prime}+qy=0"),R('特征方程',r"r^2+pr+q=0"),R('两个不同实根',r"y=C_1e^{r_1x}+C_2e^{r_2x}"),R('例题',r"y^{\prime\prime}-3y^{\prime}+2y=0,\quad(r-1)(r-2)=0"),R('结果',r"y=C_1e^x+C_2e^{2x}")],[P('二阶常系数齐次方程，看清三点：最高到二阶，各个系数是常数，右边为零。把y两撇换成r平方，把y撇换成r，把y换成一，得到特征方程。先解这个一元二次方程，再按根的类型套通解。最高阶导数前若有非零系数，可以先整体除去，或者直接保留它写特征方程。',[1,2],['常系数、二阶、右端为零','先解r的一元二次方程']),P('若有两个不同实根，就写两份指数函数的线性组合，分别配独立常数。例题特征方程r平方减三r加二，分解后根为一和二，所以通解是C一乘e的x次方，加C二乘e的二x次方。指数里面的根包含正负号，不能只保留根的绝对值。',[3,4,5],['不同实根各配一个指数','两个独立常数都要写'])],['二阶常系数齐次线性方程'])
S(c,'重根与复根：对应另外两套模板',[R('二重实根r',r"y=(C_1+C_2x)e^{rx}"),R('重根例题',r"y^{\prime\prime}-2y^{\prime}+y=0\quad\Longrightarrow\quad y=(C_1+C_2x)e^x"),R('复根',r"r=\alpha\pm i\beta,\quad\beta>0"),R('通解',r"y=e^{\alpha x}(C_1\cos\beta x+C_2\sin\beta x)"),R('例题根',r"r^2+2r+5=0\quad\Longrightarrow\quad r=-1\pm2i")],[P('若特征方程只有一个二重实根，不能把同一个指数写两遍，第二份要乘x，所以是C一加C二x，再乘e的rx次方。例题r平方减二r加一等于零，是一的二重根，套入就得到第二行。漏掉这个x，是二阶方程基础题里最常见的模板错误之一。',[1,2],['二重根的第二项必须乘x','两个相同指数相加不能代替它']),P('若根是α加减iβ，通解写成e的αx次方，乘余弦与正弦的组合。α控制外面的指数，β放在两个三角函数内部。例题根是负一加减二i，所以外面是e的负x次方，里面用余弦二x和正弦二x。三类根分别对应三套模板，先判根型再写，别让正负号或内部系数混位。',[3,4,5],['实部放指数，虚部系数放三角函数','本例外面为e的负x次方'])],['二阶常系数齐次线性方程'])
S(c,'微分方程练习',[R('题目',r"y^{\prime\prime}-y=0"),R('初值',r"y(0)=1,\quad y^{\prime}(0)=0")],[P('最后暂停做一道带初值的二阶题：y两撇减y等于零，y在零处等于一，y撇在零处等于零。先解特征方程，再写通解，把通解求导后与原式一起代入两个初值，得到关于两个常数的两条方程。不要只用其中一个初值就直接交答案。',[1,2],['先通解，再用两个初值','答案在下一页'])],['二阶常系数齐次线性方程'],kind='question')
S(c,'微分方程练习答案',[R('根与通解',r"r^2-1=0,\quad y=C_1e^x+C_2e^{-x}"),R('代入初值',r"C_1+C_2=1,\quad C_1-C_2=0"),R('结果',r"y=\frac{e^x+e^{-x}}{2}")],[P('特征根为一和负一，通解两项指数前分别放C一和C二。代入第一个初值得两常数之和为一，代入导数初值得它们之差为零，因此两常数都为二分之一，得到最后结果。你可以再求两次导数，确认y两撇确实等于y，这样原方程和两条初值就都核对过了。',[1,2,3],['两常数都等于二分之一','最后核对原方程与两条初值'])],['二阶常系数齐次线性方程'],kind='answer')
S(c,'考前回顾：按题型取基础分',[R('极限与求导',r"\lim,\quad f^{\prime},\quad f^{\prime\prime}"),R('积分',r"\int f(x)dx,\quad\int_a^b f(x)dx"),R('方程',r"y^{\prime}=gh,\quad y^{\prime}+Py=Q,\quad r^2+pr+q=0")],[P('最后按做题顺序复盘。极限先代入判型，优先约分和合法等价替换，再考虑洛必达；求导先看外内层，再看乘除与特殊形式；导数应用先写定义域，分段验号，极值与最值要代回原函数。把这些步骤写出来，即使后面运算暂时卡住，也能清楚展示已经完成的正确过程。',[1],['先拿熟悉题型的完整步骤','优先保证条件、公式和符号正确']),P('积分先分清定与不定，再选基本公式、换元或分部；不定积分加C，定积分检查上下限和奇点。面积上下相减，体积先定轴和半径；微分方程先识别三种模板，再用初值定常数。看完以后，合上答案把每章练习重新做一遍，再练本校往年基础题。练到能独立写出步骤，才算把这一个小时变成了能用的分数。',[2,3],['每章练习至少独立重做一次','本校往年题用来确认范围与写法'])],[])
